-- Additive patient records and independent booking subsystem.
create extension if not exists btree_gist;
create table if not exists patient_health_profiles(patient_id text primary key references app_users(id),dob date,gender text,blood_group text,height_cm numeric(5,1) check(height_cm>0 and height_cm<300),weight_kg numeric(6,2) check(weight_kg>0 and weight_kg<1000),notes text,units text not null default 'metric' check(units in('metric','imperial')),allergy_state text not null default 'unknown' check(allergy_state in('unknown','none_confirmed','recorded')),updated_at timestamptz not null default now());
create table if not exists patient_medical_events(id uuid primary key,patient_id text not null references app_users(id),event_type text not null check(event_type in('illness','surgery','condition','hospital','treatment','other')),title text not null,occurred_on date,description text,source text not null default 'patient' check(source in('patient','clinician')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists medical_events_patient_date on patient_medical_events(patient_id,occurred_on desc);
create table if not exists patient_medications(id uuid primary key,patient_id text not null references app_users(id),name text not null,dosage text,frequency text,start_date date,end_date date,status text not null default 'active' check(status in('active','discontinued','completed')),prescriber text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists patient_allergies(id uuid primary key,patient_id text not null references app_users(id),substance text not null,reaction text,severity text check(severity in('mild','moderate','severe','unknown')),identified_on date,notes text,created_at timestamptz not null default now());
create table if not exists patient_health_measurements(id uuid primary key,patient_id text not null references app_users(id),kind text not null check(kind in('heart_rate','systolic_bp','diastolic_bp','blood_glucose','oxygen','weight')),value numeric(10,2) not null,unit text not null,measured_at timestamptz not null,source text not null default 'patient',created_at timestamptz not null default now());
create index if not exists measurements_patient_time on patient_health_measurements(patient_id,measured_at desc);
create table if not exists patient_emergency_contacts(patient_id text primary key references app_users(id),name text,relationship text,email text,notes text,updated_at timestamptz not null default now());
create table if not exists patient_health_preferences(patient_id text primary key references app_users(id),default_days integer not null default 30 check(default_days in(7,30,90)),notify_appointments boolean not null default true,export_format text not null default 'json' check(export_format in('json','csv')),updated_at timestamptz not null default now());
create table if not exists patient_documents(id uuid primary key,patient_id text not null references app_users(id),title text not null,category text not null,mime_type text not null,size_bytes integer not null,storage_key text not null unique,notes text,source text not null default 'patient',created_at timestamptz not null default now());
create index if not exists documents_patient_date on patient_documents(patient_id,created_at desc);
create table if not exists doctor_profiles(doctor_id text primary key references doctors(id),user_id text unique references app_users(id),verified_at timestamptz,verification_source text,location text,description text,demo_only boolean not null default false,created_at timestamptz not null default now());
create table if not exists doctor_availability_rules(id uuid primary key,doctor_id text not null references doctor_profiles(doctor_id),weekday integer not null check(weekday between 0 and 6),start_minute integer not null check(start_minute between 0 and 1439),end_minute integer not null check(end_minute between 1 and 1440),duration_minutes integer not null check(duration_minutes between 10 and 180),check(start_minute<end_minute),created_at timestamptz not null default now());
create table if not exists doctor_schedule_exceptions(id uuid primary key,doctor_id text not null references doctor_profiles(doctor_id),start_at timestamptz not null,end_at timestamptz not null,reason text,check(start_at<end_at));
create table if not exists scheduled_appointments(id uuid primary key,patient_id text not null references app_users(id),doctor_id text not null references doctor_profiles(doctor_id),start_at timestamptz not null,end_at timestamptz not null,status text not null default 'requested' check(status in('requested','confirmed','rejected','cancelled','completed','no_show')),reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(start_at<end_at));
do $$ begin if not exists(select 1 from pg_constraint where conname='no_overlapping_active_appointments' and conrelid='scheduled_appointments'::regclass) then alter table scheduled_appointments add constraint no_overlapping_active_appointments exclude using gist(doctor_id with =,tstzrange(start_at,end_at,'[)') with &&) where(status in('requested','confirmed')); end if; end $$;
create index if not exists scheduled_patient_time on scheduled_appointments(patient_id,start_at desc);
create index if not exists scheduled_doctor_time on scheduled_appointments(doctor_id,start_at desc);
create table if not exists appointment_status_events(id uuid primary key,appointment_id uuid not null references scheduled_appointments(id),actor_id text not null references app_users(id),status text not null,created_at timestamptz not null default now());
create table if not exists consultation_notes(id uuid primary key,appointment_id uuid not null unique references scheduled_appointments(id),doctor_id text not null references doctor_profiles(doctor_id),summary text not null,observations text,assessment text,instructions text,medications text,released_at timestamptz,created_at timestamptz not null default now());
create table if not exists patient_doctor_consents(patient_id text not null references app_users(id),doctor_id text not null references doctor_profiles(doctor_id),granted_at timestamptz not null default now(),revoked_at timestamptz,primary key(patient_id,doctor_id));
do $$ begin if exists(select 1 from pg_roles where rolname='anon') then revoke all on patient_health_profiles,patient_medical_events,patient_medications,patient_allergies,patient_health_measurements,patient_emergency_contacts,patient_health_preferences,patient_documents,doctor_profiles,doctor_availability_rules,doctor_schedule_exceptions,scheduled_appointments,appointment_status_events,consultation_notes,patient_doctor_consents from anon; end if; if exists(select 1 from pg_roles where rolname='authenticated') then revoke all on patient_health_profiles,patient_medical_events,patient_medications,patient_allergies,patient_health_measurements,patient_emergency_contacts,patient_health_preferences,patient_documents,doctor_profiles,doctor_availability_rules,doctor_schedule_exceptions,scheduled_appointments,appointment_status_events,consultation_notes,patient_doctor_consents from authenticated; end if; end $$;
